#include <stdio.h>
int main(){
    double x=1, w1=0.6, w2=1, eta=0.1, t=0;
    double zh=w1*x;
    double ah=zh; // linear
    double zo=w2*ah;
    double y=zo;
    double delta_o=(y-t); // derivative =1
    double delta_h=w2*delta_o; // derivative =1
    double w1_new=w1-eta*delta_h*x;
    printf("%0.2f\n", w1_new);
    return 0;
}
